/** Crop coefficient by stage, used for irrigation (ET0 x Kc). */
export const KC: Record<Stage, number> = {
  rest: 0.3,
  bahar: 0.45,
  flowering: 0.65,
  fruitset: 0.75,
  development: 0.9,
  maturity: 0.75,
  harvest: 0.7,
  done: 0.3,
};

export function stageOn(day: number, baharStart: number, harvestStart: number, lastPick: number): Stage {
  if (day < baharStart) return "rest";
  if (day < baharStart + 30) return "bahar";
  if (day < baharStart + 55) return "flowering";
  if (day < baharStart + 80) return "fruitset";
  if (day < harvestStart - 20) return "development";
  if (day < harvestStart) return "maturity";
  if (day <= lastPick) return "harvest";
  return "done";
}

